function fig = plotBnpCountPosterior(result, photophysics, opts)
%PLOTBNPCOUNTPOSTERIOR Show framewise and total emitter-count probabilities.

    probability = result.frameEmitterCountProbability;
    countValues = 0:size(probability, 2)-1;
    frame = (1:size(probability, 1)).';
    trueExpectedSignal = photophysics.detectedRateS * opts.dtS;
    trueInFocus = sum( ...
        trueExpectedSignal >= ...
        opts.bnpInFocusPhotonThreshold, 1).';

    fig = figure('Color', 'w', 'Position', [120 100 980 720]);
    layout = tiledlayout(fig, 2, 1, 'Padding', 'compact', ...
        'TileSpacing', 'compact');

    ax = nexttile(layout);
    imagesc(ax, frame, countValues, probability.');
    axis(ax, 'xy');
    hold(ax, 'on');
    mapLine = plot(ax, frame, ...
        result.frameEmitterCountPosterior.mapCount, ...
        'w-', 'LineWidth', 1.1);
    truthLine = plot(ax, frame, trueInFocus, '-', ...
        'Color', [0.1 0.95 0.4], ...
        'LineWidth', 0.9);
    xlabel(ax, 'frame');
    ylabel(ax, 'emitters in focus');
    title(ax, sprintf([ ...
        'Frame count posterior: median MAP probability %.3f, ' ...
        'mean occupancy %.2f'], ...
        result.medianFrameCountDecisionProbability, ...
        result.posteriorMeanEmittersInFocus));
    colorScale = colorbar(ax);
    colorScale.Label.String = 'posterior probability';
    legend(ax, [mapLine truthLine], ...
        {'posterior MAP', 'simulation truth'}, ...
        'Location', 'northeast');

    ax = nexttile(layout);
    bar(ax, countValues, result.activeEmitterCountProbability, 0.85, ...
        'FaceColor', [0.15 0.48 0.70], 'EdgeColor', 'none');
    hold(ax, 'on');
    xline(ax, result.posteriorMapActiveEmitterCount, 'k-', ...
        'LineWidth', 1.2);
    xline(ax, result.trueContributingMolecules, '--', ...
        'Color', [0.85 0.33 0.10], 'LineWidth', 1.2);
    xlabel(ax, 'total active emitter identities');
    ylabel(ax, 'posterior probability');
    title(ax, sprintf([ ...
        'Total MAP %d, P = %.3f, entropy %.2f bits, ' ...
        'adjacent-count separation %.2f sigma'], ...
        result.posteriorMapActiveEmitterCount, ...
        result.activeEmitterCountDecisionProbability, ...
        result.activeEmitterCountEntropyBits, ...
        result.adjacentCountSeparationSigma));
    legend(ax, {'posterior', 'posterior MAP', ...
        'simulation contributing identities'}, 'Location', 'best');
    grid(ax, 'on');

    title(layout, sprintf( ...
        'Brightness-constrained BNP counting (%s brightness)', ...
        result.brightnessMode), 'FontWeight', 'bold');
end
